// src/pages/AddNote.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api';

const AddNote = () => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [tags, setTags] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();

    API.post('/notes', {
      title,
      body,
      tags: tags.split(',').map((tag) => tag.trim()),
    })
      .then(() => navigate('/'))
      .catch((err) => console.error(err));
  };

  return (
    <div>
      <h2>Tambah Catatan</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" placeholder="Judul" value={title} onChange={(e) => setTitle(e.target.value)} required />
        <br />
        <textarea placeholder="Isi" value={body} onChange={(e) => setBody(e.target.value)} required />
        <br />
        <input type="text" placeholder="Tags (pisah dengan koma)" value={tags} onChange={(e) => setTags(e.target.value)} />
        <br />
        <button type="submit">Simpan</button>
      </form>
    </div>
  );
};

export default AddNote;
